import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable, BehaviorSubject } from 'rxjs';
import { tap, catchError } from 'rxjs/operators';

// Keycloak конфигурация - ЗАМЕНИТЕ НА ВАШИ НАСТРОЙКИ
const keycloakConfig = {
  url: 'http://localhost:8080/auth', // URL вашего Keycloak контейнера
  realm: 'master',                   // Название realm (по умолчанию master)
  clientId: 'admin-cli'              // ID клиента (по умолчанию admin-cli)
};

@Injectable({
  providedIn: 'root'
})
export class KeycloakService {
  private isAuthenticatedSubject = new BehaviorSubject<boolean>(false);
  private userProfileSubject = new BehaviorSubject<any>(null);

  public isAuthenticated$ = this.isAuthenticatedSubject.asObservable();
  public userProfile$ = this.userProfileSubject.asObservable();

  constructor(private http: HttpClient) {
    this.checkAuthStatus();
  }

  /**
   * Стандартный вход через редирект на страницу Keycloak
   */
  login(): void {
    const keycloakLoginUrl = `${keycloakConfig.url}/realms/${keycloakConfig.realm}/protocol/openid-connect/auth` +
      `?client_id=${keycloakConfig.clientId}` +
      `&redirect_uri=${encodeURIComponent(window.location.origin)}` +
      `&response_type=code` +
      `&scope=openid`;

    window.location.href = keycloakLoginUrl;
  }

  /**
   * Прямой вход (Resource Owner Password Credentials Grant)
   */
  loginDirect(username: string, password: string): Observable<boolean> {
    const body = new URLSearchParams();
    body.set('client_id', keycloakConfig.clientId);
    body.set('username', username);
    body.set('password', password);
    body.set('grant_type', 'password');
    body.set('scope', 'openid');

    const headers = new HttpHeaders({
      'Content-Type': 'application/x-www-form-urlencoded'
    });

    return this.http.post<any>(
      `${keycloakConfig.url}/realms/${keycloakConfig.realm}/protocol/openid-connect/token`,
      body.toString(),
      { headers }
    ).pipe(
      tap(response => {
        localStorage.setItem('access_token', response.access_token);
        localStorage.setItem('refresh_token', response.refresh_token);
        localStorage.setItem('token_type', response.token_type);

        this.isAuthenticatedSubject.next(true);
        this.loadUserProfile();
      }),
      catchError(error => {
        console.error('Direct login error:', error);
        throw error;
      })
    );
  }

  /**
   * Выход
   */
  logout(): void {
    const token = localStorage.getItem('access_token');
    localStorage.clear();
    this.isAuthenticatedSubject.next(false);
    this.userProfileSubject.next(null);

    const logoutUrl = `${keycloakConfig.url}/realms/${keycloakConfig.realm}/protocol/openid-connect/logout` +
      `?post_logout_redirect_uri=${encodeURIComponent(window.location.origin)}`;

    window.location.href = logoutUrl;
  }

  /**
   * Регистрация нового пользователя
   */
  register(): void {
    const registerUrl = `${keycloakConfig.url}/realms/${keycloakConfig.realm}/protocol/openid-connect/registrations` +
      `?client_id=${keycloakConfig.clientId}` +
      `&redirect_uri=${encodeURIComponent(window.location.origin)}` +
      `&response_type=code` +
      `&scope=openid`;

    window.location.href = registerUrl;
  }

  /**
   * Восстановление пароля
   */
  forgotPassword(): void {
    const resetUrl = `${keycloakConfig.url}/realms/${keycloakConfig.realm}/login-actions/reset-credentials` +
      `?client_id=${keycloakConfig.clientId}`;

    window.location.href = resetUrl;
  }

  /**
   * Проверка статуса аутентификации
   */
  isLoggedIn(): boolean {
    return this.isAuthenticatedSubject.value;
  }

  /**
   * Получение токена
   */
  getToken(): string | null {
    return localStorage.getItem('access_token');
  }

  /**
   * Получение информации о пользователе
   */
  getUser(): any {
    return this.userProfileSubject.value;
  }

  /**
   * Проверка роли пользователя
   */
  hasRole(role: string): boolean {
    const user = this.getUser();
    return user && user.roles && user.roles.includes(role);
  }

  /**
   * Загрузка профиля пользователя
   */
  private loadUserProfile(): void {
    const token = this.getToken();
    if (!token) return;

    // Здесь можно загрузить дополнительную информацию о пользователе
    console.log('User profile loaded');
  }

  /**
   * Проверка статуса аутентификации при загрузке приложения
   */
  private checkAuthStatus(): void {
    const urlParams = new URLSearchParams(window.location.search);
    const code = urlParams.get('code');

    if (code) {
      this.exchangeCodeForToken(code);
    } else {
      const token = localStorage.getItem('access_token');
      if (token) {
        this.isAuthenticatedSubject.next(true);
        this.loadUserProfile();
      }
    }
  }

  /**
   * Обмен authorization code на access token
   */
  private exchangeCodeForToken(code: string): void {
    const body = new URLSearchParams();
    body.set('client_id', keycloakConfig.clientId);
    body.set('code', code);
    body.set('grant_type', 'authorization_code');
    body.set('redirect_uri', window.location.origin);

    const headers = new HttpHeaders({
      'Content-Type': 'application/x-www-form-urlencoded'
    });

    this.http.post<any>(
      `${keycloakConfig.url}/realms/${keycloakConfig.realm}/protocol/openid-connect/token`,
      body.toString(),
      { headers }
    ).subscribe({
      next: (response) => {
        localStorage.setItem('access_token', response.access_token);
        localStorage.setItem('refresh_token', response.refresh_token);
        this.isAuthenticatedSubject.next(true);
        this.loadUserProfile();

        // Очищаем URL от параметров
        window.history.replaceState({}, document.title, window.location.pathname);
      },
      error: (error) => {
        console.error('Token exchange error:', error);
      }
    });
  }
}
